-- Internal Message Broker full install: database, schema and bootstrap data. Generated by
-- db/build-release-script.ps1 -Full; do not edit.
--
-- From PowerShell, use the wrapper, which passes the values for you:
--   ./db/install-database.ps1 -Server <server> -AdminApiKey <key> -WebhookAllowedHosts hooks.example.com
-- From cmd, run sqlcmd -b connected to any database on the server, passing every variable ("" for none):
--   sqlcmd -b -S <server> -i db\BrokerDb_Full.sql -v DatabaseName="BrokerDb" AdminName="broker-admin"
--          AdminApiKey="<key>" WebhookAllowedHosts="hooks.example.com,10.0.0.5"
--
--   DatabaseName         created when missing.
--   AdminName            the Admin application; empty means broker-admin.
--   AdminApiKey          its first key, from: dotnet run --project src/MessageBroker.Api -- new-api-key
--                        Only the SHA-256 hash is stored. Empty adds no key.
--   WebhookAllowedHosts  comma-separated hosts webhooks may call; empty adds none.
--
-- In SSMS, switch on Query > SQLCMD Mode and add a :setvar line for each variable at the top.
SET QUOTED_IDENTIFIER ON;
GO
DECLARE @Variables nvarchar(max) = N'$(DatabaseName)$(AdminName)$(AdminApiKey)$(WebhookAllowedHosts)';
