-- ===== MessageBroker.Infrastructure.db.Programmability.Functions.fn_HasPermission.sql
-- Returns one row with Allowed = 1 when the application is an active admin, or holds the permission
-- (or Manage) on the resource. Used by every procedure that acts on behalf of a caller.
CREATE OR ALTER FUNCTION broker.fn_HasPermission
(
    @AppId        uniqueidentifier,
    @ResourceType varchar(20),
    @ResourceId   uniqueidentifier,
    @Permission   varchar(20)
)
RETURNS TABLE
AS
RETURN
    SELECT CAST(CASE
        WHEN EXISTS (SELECT 1 FROM broker.Applications a
                     WHERE a.AppId = @AppId AND a.IsActive = 1 AND a.IsAdmin = 1) THEN 1
        WHEN EXISTS (SELECT 1 FROM broker.AppPermissions p
                     JOIN broker.Applications a ON a.AppId = p.AppId AND a.IsActive = 1
                     WHERE p.AppId = @AppId
                       AND p.ResourceType = @ResourceType
                       AND p.ResourceId = @ResourceId
                       AND p.Permission IN (@Permission, 'Manage')) THEN 1
        ELSE 0 END AS bit) AS Allowed;
GO
GO

-- ===== MessageBroker.Infrastructure.db.Programmability.Views.Views.sql
-- [Fix 12] Derived message status. Cancelled deliveries are ignored: a deleted subscription says
-- nothing about whether the message was processed. A message with no deliveries is Completed.
CREATE OR ALTER VIEW broker.vw_MessageStatus
AS
SELECT
    m.MessageId,
    CASE
        WHEN SUM(CASE WHEN d.Status IN (0, 1) THEN 1 ELSE 0 END) > 0 THEN 'InProgress'
        WHEN SUM(CASE WHEN d.Status = 3 THEN 1 ELSE 0 END) = 0 THEN 'Completed'
        WHEN SUM(CASE WHEN d.Status = 3 THEN 1 ELSE 0 END) = SUM(CASE WHEN d.Status <> 4 THEN 1 ELSE 0 END) THEN 'DeadLettered'
        ELSE 'PartiallyDeadLettered'
    END AS Status,
    COUNT(d.DeliveryId) AS DeliveryCount,
    SUM(CASE WHEN d.Status = 0 THEN 1 ELSE 0 END) AS PendingCount,
    SUM(CASE WHEN d.Status = 1 THEN 1 ELSE 0 END) AS LeasedCount,
    SUM(CASE WHEN d.Status = 2 THEN 1 ELSE 0 END) AS CompletedCount,
    SUM(CASE WHEN d.Status = 3 THEN 1 ELSE 0 END) AS DeadLetteredCount,
    SUM(CASE WHEN d.Status = 4 THEN 1 ELSE 0 END) AS CancelledCount
FROM broker.Messages m
LEFT JOIN broker.Deliveries d ON d.MessageId = m.MessageId
GROUP BY m.MessageId;
GO

-- Backlog and DLQ size per subscription (spec section 13, operational queries).
CREATE OR ALTER VIEW broker.vw_SubscriptionDeliveryCounts
AS
SELECT
    s.SubscriptionId,
    SUM(CASE WHEN d.Status = 0 THEN 1 ELSE 0 END) AS PendingCount,
    SUM(CASE WHEN d.Status = 1 THEN 1 ELSE 0 END) AS LeasedCount,
    SUM(CASE WHEN d.Status = 3 THEN 1 ELSE 0 END) AS DeadLetteredCount
FROM broker.Subscriptions s
LEFT JOIN broker.Deliveries d ON d.SubscriptionId = s.SubscriptionId AND d.Status IN (0, 1, 3)
GROUP BY s.SubscriptionId;
GO

-- Subscription with its topic name and delivery counts; the shape returned by the subscription procedures.
CREATE OR ALTER VIEW broker.vw_SubscriptionDetails
AS
SELECT
    s.SubscriptionId,
    s.TopicId,
    t.Name AS TopicName,
    s.Name,
    s.OwnerAppId,
    s.Status,
    s.DeliveryMode,
    s.WebhookUrl,
    s.WebhookSecret,
    s.PreviousWebhookSecret,
    s.PreviousSecretExpiresAt,
    s.WebhookTimeoutSeconds,
    s.MaxConcurrentDeliveries,
    s.MaxAttempts,
    s.LockDurationSeconds,
    s.RetryBaseDelaySeconds,
    s.RetryMaxDelaySeconds,
    s.TtlSeconds,
    s.CreatedAt,
    s.UpdatedAt,
    c.PendingCount,
    c.LeasedCount,
    c.DeadLetteredCount
FROM broker.Subscriptions s
JOIN broker.Topics t ON t.TopicId = s.TopicId
JOIN broker.vw_SubscriptionDeliveryCounts c ON c.SubscriptionId = s.SubscriptionId;
GO

-- A DLQ entry with the message and names an operator needs, without copying the payload.
CREATE OR ALTER VIEW broker.vw_DeadLetterDetails
AS
SELECT
    dl.DeadLetterId,
    dl.DeliveryId,
    dl.MessageId,
    dl.SubscriptionId,
    s.Name AS SubscriptionName,
    dl.TopicId,
    t.Name AS TopicName,
    dl.Reason,
    dl.AttemptCount,
    dl.LastError,
    dl.FirstFailureAt,
    dl.LastFailureAt,
    dl.DeadLetteredAt,
    dl.RequeuedAt,
    dl.RequeuedBy,
    m.MessageType,
    m.CorrelationId,
    m.CreatedAt AS MessageCreatedAt,
    m.Properties,
    m.Payload
FROM broker.DeadLetters dl
JOIN broker.Messages m ON m.MessageId = dl.MessageId
JOIN broker.Subscriptions s ON s.SubscriptionId = dl.SubscriptionId
JOIN broker.Topics t ON t.TopicId = dl.TopicId;
GO

-- Push subscriptions the lease loop works on. HasDueDeliveries lets it skip idle subscriptions cheaply.
CREATE OR ALTER VIEW broker.vw_ActivePushSubscriptions
AS
SELECT
    s.SubscriptionId,
    s.TopicId,
    s.Name,
    s.DeliveryMode,
    s.WebhookUrl,
    s.WebhookSecret,
    s.PreviousWebhookSecret,
    s.PreviousSecretExpiresAt,
    s.WebhookTimeoutSeconds,
    s.MaxConcurrentDeliveries,
    s.LockDurationSeconds,
    -- Compared with the clock at millisecond precision, as usp_Delivery_Lease does: a stored
    -- datetime2(3) can be rounded up, and against the raw clock a delivery published within the last
    -- half millisecond would look not yet due, so the lease loop would skip it until its next pass.
    CAST(CASE WHEN EXISTS (
        SELECT 1 FROM broker.Deliveries d
        WHERE d.SubscriptionId = s.SubscriptionId
          AND d.Status = 0
          AND d.AvailableAt <= CAST(SYSUTCDATETIME() AS datetime2(3))
          AND (d.ExpiresAt IS NULL OR d.ExpiresAt > CAST(SYSUTCDATETIME() AS datetime2(3)))) THEN 1 ELSE 0 END AS bit) AS HasDueDeliveries
FROM broker.Subscriptions s
WHERE s.Status = 'Active'
  AND s.DeliveryMode IN ('Webhook', 'SignalR');
GO
GO

-- ===== MessageBroker.Infrastructure.db.Programmability.Procedures.Auth.sql
-- Applications, API keys and permissions.
-- Error numbers: 50400 validation, 50403 forbidden, 50404 not found, 50409 conflict, 50410 lease lost.

CREATE OR ALTER PROCEDURE broker.usp_Application_Create
    @AppId   uniqueidentifier,
    @Name    nvarchar(100),
    @IsAdmin bit
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;

    IF EXISTS (SELECT 1 FROM broker.Applications WHERE Name = @Name)
        THROW 50409, N'An application with this name already exists.', 1;

    INSERT broker.Applications (AppId, Name, IsAdmin) VALUES (@AppId, @Name, @IsAdmin);

    SELECT AppId, Name, IsAdmin, IsActive, CreatedAt FROM broker.Applications WHERE AppId = @AppId;
END
GO

CREATE OR ALTER PROCEDURE broker.usp_Application_Get
    @AppId uniqueidentifier
AS
BEGIN
    SET NOCOUNT ON;
    SELECT AppId, Name, IsAdmin, IsActive, CreatedAt FROM broker.Applications WHERE AppId = @AppId;
END
GO

CREATE OR ALTER PROCEDURE broker.usp_Application_List
AS
BEGIN
    SET NOCOUNT ON;
    SELECT AppId, Name, IsAdmin, IsActive, CreatedAt FROM broker.Applications ORDER BY Name;
END
GO

CREATE OR ALTER PROCEDURE broker.usp_Application_SetActive
    @AppId    uniqueidentifier,
    @IsActive bit
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;

    UPDATE broker.Applications SET IsActive = @IsActive WHERE AppId = @AppId;
    IF @@ROWCOUNT = 0
        THROW 50404, N'Application was not found.', 1;
END
GO

-- [Fix 6] At most two active, unexpired keys per application, so keys can be rotated without downtime.
CREATE OR ALTER PROCEDURE broker.usp_ApiKey_Create
    @KeyId     uniqueidentifier,
    @AppId     uniqueidentifier,
    @Prefix    varchar(32),
    @Hash      varbinary(32),
    @ExpiresAt datetime2(3) = NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;

    BEGIN TRAN;

    IF NOT EXISTS (SELECT 1 FROM broker.Applications WITH (UPDLOCK, HOLDLOCK) WHERE AppId = @AppId)
    BEGIN
        ROLLBACK;
        THROW 50404, N'Application was not found.', 1;
    END

    IF (SELECT COUNT(*) FROM broker.ApiKeys
        WHERE AppId = @AppId AND IsActive = 1 AND (ExpiresAt IS NULL OR ExpiresAt > SYSUTCDATETIME())) >= 2
    BEGIN
        ROLLBACK;
        THROW 50409, N'The application already has two active keys. Deactivate one before issuing another.', 1;
    END

    INSERT broker.ApiKeys (KeyId, AppId, Prefix, Hash, ExpiresAt) VALUES (@KeyId, @AppId, @Prefix, @Hash, @ExpiresAt);

    COMMIT;

    SELECT KeyId, AppId, Prefix, IsActive, CreatedAt, ExpiresAt FROM broker.ApiKeys WHERE KeyId = @KeyId;
END
GO

CREATE OR ALTER PROCEDURE broker.usp_ApiKey_Deactivate
    @AppId uniqueidentifier,
    @KeyId uniqueidentifier
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;

    UPDATE broker.ApiKeys SET IsActive = 0 WHERE KeyId = @KeyId AND AppId = @AppId;
    IF @@ROWCOUNT = 0
        THROW 50404, N'API key was not found.', 1;
END
GO

CREATE OR ALTER PROCEDURE broker.usp_ApiKey_List
    @AppId uniqueidentifier
AS
BEGIN
    SET NOCOUNT ON;
    SELECT KeyId, AppId, Prefix, IsActive, CreatedAt, ExpiresAt
    FROM broker.ApiKeys WHERE AppId = @AppId ORDER BY CreatedAt;
END
GO

-- Authentication lookup. Only keys that are active, unexpired and belong to an active application resolve.
CREATE OR ALTER PROCEDURE broker.usp_ApiKey_GetByPrefix
    @Prefix varchar(32)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT k.KeyId, k.AppId, k.Hash, a.Name AS AppName, a.IsAdmin
    FROM broker.ApiKeys k
    JOIN broker.Applications a ON a.AppId = k.AppId
    WHERE k.Prefix = @Prefix
      AND k.IsActive = 1
      AND a.IsActive = 1
      AND (k.ExpiresAt IS NULL OR k.ExpiresAt > SYSUTCDATETIME());
END
GO

-- Creates the first admin application and key from configuration. Safe to run on every start.
CREATE OR ALTER PROCEDURE broker.usp_Application_EnsureBootstrapAdmin
    @AppId  uniqueidentifier,
    @Name   nvarchar(100),
    @KeyId  uniqueidentifier,
    @Prefix varchar(32),
    @Hash   varbinary(32)
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;

    BEGIN TRAN;

    IF NOT EXISTS (SELECT 1 FROM broker.ApiKeys WITH (UPDLOCK, HOLDLOCK) WHERE Prefix = @Prefix)
    BEGIN
        DECLARE @ExistingAppId uniqueidentifier = (SELECT AppId FROM broker.Applications WHERE Name = @Name);
        IF @ExistingAppId IS NULL
            INSERT broker.Applications (AppId, Name, IsAdmin) VALUES (@AppId, @Name, 1);
        ELSE
            SET @AppId = @ExistingAppId;

        INSERT broker.ApiKeys (KeyId, AppId, Prefix, Hash) VALUES (@KeyId, @AppId, @Prefix, @Hash);
    END

    COMMIT;
END
GO

CREATE OR ALTER PROCEDURE broker.usp_Permission_Grant
    @AppId        uniqueidentifier,
    @ResourceType varchar(20),
    @ResourceId   uniqueidentifier,
    @Permission   varchar(20)
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;

    IF NOT EXISTS (SELECT 1 FROM broker.Applications WHERE AppId = @AppId)
        THROW 50404, N'Application was not found.', 1;

    IF (@ResourceType = 'Topic' AND NOT EXISTS (SELECT 1 FROM broker.Topics WHERE TopicId = @ResourceId AND IsDeleted = 0))
       OR (@ResourceType = 'Subscription' AND NOT EXISTS (SELECT 1 FROM broker.Subscriptions WHERE SubscriptionId = @ResourceId AND Status <> 'Deleted'))
        THROW 50404, N'The resource was not found.', 1;

    IF NOT EXISTS (SELECT 1 FROM broker.AppPermissions
                   WHERE AppId = @AppId AND ResourceType = @ResourceType AND ResourceId = @ResourceId AND Permission = @Permission)
        INSERT broker.AppPermissions (AppId, ResourceType, ResourceId, Permission)
        VALUES (@AppId, @ResourceType, @ResourceId, @Permission);
END
